import re
from .epc_section_generic import EpcSectionGeneric, EpcLine
from ..utils.logger import logger


class SectionAmf(EpcSectionGeneric):
    """
    Section "Amf" is a part of epc.lua config file.
    Generated content base on epc.yaml.
    Example generated for CLOUD_R4A_CUS:

    exec("set_amf_region id=1 tac_list=7627107,100,788,200,0 plmn=311:489")
    exec("set_amf id=1 daemon=:10000 ng=10.0.1.1:38412 region=1 set_id=2 pointer=2")
    exec("amf_param id=1 full_nas_auth=on nia=null+zuc nea=null+zuc")
    exec("amf_param id=1 ims_voice_3gpp=on full_nas_auth=on")
    """

    def _prepare_section_content(self, epc_config, *args, **kwargs):
        amf_keys = filter(self._filter_amf, sorted(epc_config.keys()))
        if not amf_keys:
            return
        logger.debug("Generating AMF section")
        subsection = []
        for amf in amf_keys:
            amf_data = epc_config[amf]
            amf_num = re.match(r'amf(?P<amf_num>\d+)', amf).group('amf_num')
            tac_list = amf_data['tac_list']
            mcc = amf_data['mcc']
            mnc = amf_data['mnc']
            set_id = amf_data['set_id']
            pointer = amf_data['pointer']
            ng_addr = amf_data['ip_addr']

            # set_amf_region id=1 tac_list=7627107,100,788,200,0 plmn=311:489
            # set_amf id=1 daemon=$SERVER_IP:$DAEMON_PORT ng=$AMF_NG_ADDR:38412 region=1 set_id=2 pointer=2
            # amf_param id=1 full_nas_auth=on nia=null+zuc nea=null+zuc
            amf_lines = [
                f"set_amf_region id={amf_num} tac_list={tac_list} plmn={mcc}:{mnc}",
                f"set_amf id={amf_num} daemon=:{self.EDAEMON_PORT} ng={ng_addr}:38412 region={amf_num} set_id={set_id} pointer={pointer}",
                f"amf_param id={amf_num} full_nas_auth=on nia=null+zuc nea=null+zuc",
                f"amf_param id={amf_num} ims_voice_3gpp=on full_nas_auth=on",
            ]
            for amf_line in amf_lines:
                subsection.append(EpcLine(line=amf_line, exec=True, tab_count=0))

        self._section_content.append(subsection)

    @staticmethod
    def _filter_amf(s: str):
        return re.match(r'amf\d+', s) is not None
